package ir.codelighthouse.bazikhooneh;
import android.os.Bundle;import android.widget.TextView;import ir.codelighthouse.bazikhooneh.account.*;import org.json.*;
public final class SessionsActivity extends NavigableActivity{private AccountManagementClient client;private TextView status;
 @Override protected void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_sessions);SessionStore store=new SessionStore(this);client=new AccountManagementClient(BuildConfig.API_BASE_URL,store.token(),listener);status=findViewById(R.id.sessions_status);findViewById(R.id.revoke_sessions).setOnClickListener(v->client.delete("revoke","/api/v1/accounts/sessions/"));load();}private void load(){client.get("list","/api/v1/accounts/sessions/");}
 private final AccountManagementClient.Listener listener=new AccountManagementClient.Listener(){public void onSuccess(String o,JSONObject j){runOnUiThread(()->{if("list".equals(o)){org.json.JSONArray results=j.optJSONArray("results");status.setText(getString(R.string.active_sessions_count,results==null?0:results.length()));}else{status.setText(R.string.other_sessions_revoked);load();}});}public void onError(String e){runOnUiThread(()->status.setText(AccountErrorMessages.get(SessionsActivity.this,e)));}};}
